import sys


def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        idx += 2
        adj[u].append(v)
        adj[v].append(u)
    W = [int(data[idx + i]) for i in range(n)]
    idx += n
    A = [int(data[idx + i]) for i in range(n)]

    # f[x] = max number of operations generated by a single piece on x:
    # f[x] = 1 + max sum of f[y] over neighbor sets S with sum W[y] <= W[x] - 1.
    # Neighbors with W[y] < W[x] are finished first when processing by increasing W.
    f = [0] * n
    order = sorted(range(n), key=lambda i: W[i])
    for x in order:
        cap = W[x] - 1
        dp = [0] * (cap + 1)  # dp[c] = best value with total weight <= c (0/1 knapsack)
        for y in adj[x]:
            w = W[y]
            if w > cap:
                continue
            v = f[y]
            tmp = [b + v for b in dp[:cap + 1 - w]]
            dp[w:] = list(map(max, dp[w:], tmp))
        f[x] = 1 + dp[cap]

    print(sum(A[i] * f[i] for i in range(n)))


main()
